const sleep = ms => new Promise(r => setTimeout(r, ms));

// Same PLAN as playthrough (9 d-major,7 i,4 s,4 c; 4 d-minor,5 i,7 s,8 c)
const PLAN = (() => {
  const maj = { d: 9, i: 7, s: 4, c: 4 };
  const min = { d: 4, i: 5, s: 7, c: 8 };
  const pairs = [];
  for (let i = 0; i < 24; i++) {
    const cands = Object.keys(maj)
      .filter(t => maj[t] > 0)
      .filter(t => Object.keys(min).some(m => m !== t && min[m] > 0))
      .sort((a, b) => maj[b] - maj[a]);
    const M = cands[0];
    const m = Object.keys(min).filter(x => x !== M && min[x] > 0).sort((a, b) => min[b] - min[a])[0];
    maj[M]--; min[m]--; pairs.push([M, m]);
  }
  return pairs;
})();
const EXPECTED = (() => {
  const s = { d: 0, i: 0, s: 0, c: 0 };
  PLAN.forEach(([a, b]) => { s[a]++; s[b]--; });
  return s;
})();

const norm = t => (t || '').replace(/\s+/g, ' ').trim();
const refQ = JSON.parse(fs.readFileSync('/home/dp/MyProjects/disc/test-assignment/reference/questions.json', 'utf8'));
const refMap = {};
for (const q of refQ.questions) for (const it of q.items) refMap[norm(it.text)] = it.type;
const RMJ = JSON.stringify(refMap);

// read a specific question's list rows from the active pane
async function getRows(page, q) {
  return page.evaluate((qi, rmj) => {
