  await sleep(600);

  // real mouse drag with steps
  async function dragMouse(sx, sy, dx, dy, steps = 14) {
    await page.mouse.move(sx, sy, { steps: 6 });
    await sleep(40);
    await page.mouse.down();
    await sleep(30);
    for (let i = 1; i <= steps; i++) {
      const cx = sx + (dx - sx) * (i / steps);
