    if (ok) res.dragOk++;
    else { res.dragFail++; res.fails.push({ q, got, want: [majT, null, null, minT] }); }
    res.processed++;
    if ((q + 1) % 4 === 0) console.log('progress ' + (q + 1) + '/24  ok=' + res.dragOk + ' fail=' + res.dragFail);
  }

  await sleep(500);
  await page.evaluate(() => {
    const f = document.querySelector('[data-disc-finish]');
    if (f) { f.hidden = false; f.click(); }
  });
