  if (res.fails.length) {
    console.log('\nFAILS:');
    console.log(JSON.stringify(res.fails.slice(0, 20), null, 2));
  } else {
    console.log('\nAll 24 questions reordered correctly by real mouse drags!');
  }
  await browser.close();
}
