    await page.mouse.down();
    await sleep(30);
    for (let i = 1; i <= steps; i++) {
      const cx = sx + (dx - sx) * (i / steps);
      const cy = sy + (dy - sy) * (i / steps);
      await page.mouse.move(cx, cy, { steps: 4 });
      await sleep(20);
    }
    await page.mouse.up();
    await sleep(80);
  };

