      const items = [...ul.children];
      return items.map((li, i) => {
        const r = li.getBoundingClientRect();
        const h = li.querySelector('.disc-handle');
        const hr = h ? h.getBoundingClientRect() : null;
        return { i, type: li.getAttribute('data-type'),
