      const ul = uls[qi % 3];
      if (ul) ul.scrollIntoView({ block: 'center', behavior: 'instant' });
    }, q);
    await sleep(250);

    let rows = await read();
    if (!rows || rows.length !== 4) { res.fail++; res.fails.push({ q, problem: 'no list' }); continue; }
    rows = await read();
    if (!rows || rows.length !== 4) { res.fail++; res.fails.push({ q, problem: 'no list 2' }); continue; }

