    let maj = t0, min = t1;
    // make sure maj and min are different
    if (t1 === t0) {
      // find another
      if (t2 !== t0) { maj = t0; min = t2; }
      else if (t3 !== t0) { maj = t0; min = t3; }
    }
    let majRow = rows.find(r => r.type === maj);
    let minRow = rows.find(r => r.type === min);
    if (!majRow || !minRow) { res.fail++; res.fails.push({ q, problem: 'missing', maj, min }); continue; }

