    await sleep(120);
    const after = await read();
    if (!after || after.length !== 4) { res.fail++; res.fails.push({ q, problem: 'after maj drag no list' }); continue; }
    let minRow2 = after.find(r => r.type === min);
    if (!minRow2) { res.fail++; res.fails.push({ q, problem: 'no min after' }); continue; }
    if (!minRow2.h) { res.fail++; res.fails.push({ q, problem: 'no min handle' }); continue; }
    await dragMouse(minRow2.h.cx, minRow2.h.cy, after[3].h ? after[3].h.cx : after[3].cx, after[3].bottom - 5);
    await sleep(120);

    const fin = await read();
    const got = fin && fin.length === 4 ? fin.map(r => r.type) : null;
    const ok = got && got[0] === maj && got[3] === min;
    if (ok) res.ok++; else { res.fail++; res.fails.push({ q, got, want: [maj, null, null, min] }); }
    res.tested++;
  }

