  await sleep(700);

  console.log('coarse (matchMedia) =', await page.evaluate(() => window.matchMedia('(pointer: coarse)').matches));
  console.log('body has disc-coarse =', await page.evaluate(() => document.body.classList.contains('disc-coarse')));
  console.log('handle pointer-events =', await page.evaluate(() => getComputedStyle(document.querySelector('.disc-handle')).pointerEvents));
  console.log('handle size =', await page.evaluate(() => {
    const h = document.querySelector('.disc-handle');
    const r = h.getBoundingClientRect();
    return { w: r.width, h: r.height };
  }));

  await page.click('[data-modal-open]');
  await sleep(600);

  const dragMouse = async (sx, sy, dx, dy, steps = 14) => {
    if (!Number.isFinite(sx) || !Number.isFinite(sy) || !Number.isFinite(dx) || !Number.isFinite(dy))
      throw new Error('NaN/undefined drag coords: s=(' + sx + ',' + sy + ') d=(' + dx + ',' + dy + ')');
    await page.mouse.move(sx, sy, { steps: 6 });
    await sleep(40);
    await page.mouse.down();
    await sleep(30);
    for (let i = 1; i <= steps; i++) {
      const cx = sx + (dx - sx) * (i / steps);
      const cy = sy + (dy - sy) * (i / steps);
      await page.mouse.move(cx, cy, { steps: 4 });
      await sleep(20);
    }
    await page.mouse.up();
    await sleep(80);
  };

  const read = async () => {
    return page.evaluate(() => {
      const pane = document.querySelector('.pane.is-active');
      const ul = pane ? pane.querySelector('ul.disc-list') : null;
      if (!ul) return null;
      const items = [...ul.children];
      return items.map((li, i) => {
        const r = li.getBoundingClientRect();
        const h = li.querySelector('.disc-handle');
        const hr = h ? h.getBoundingClientRect() : null;
        return { i, type: li.getAttribute('data-type'), text: li.textContent.trim(),
                 cx: r.left + r.width / 2, cy: r.top + r.height / 2,
                 h: hr ? { cx: hr.left + hr.width / 2, cy: hr.top + hr.height / 2 } : null };
      });
    });
  };

  const res = { tested: 0, ok: 0, fail: 0, fails: [] };
  for (let q = 0; q < 5; q++) {
    await page.evaluate((si) => {
      const tab = document.querySelector('[data-step-btn="' + si + '"]');
      if (tab) tab.click();
    }, Math.floor(q / 3));
    await sleep(350);
    await page.evaluate((qi) => {
      const pane = document.querySelector('.pane.is-active');
      const uls = [...pane.querySelectorAll('ul.disc-list')];
      const ul = uls[qi % 3];
      if (ul) ul.scrollIntoView({ block: 'center', behavior: 'instant' });
    }, q);
    await sleep(250);

    let rows = await read();
    if (!rows || rows.length !== 4) { res.fail++; res.fails.push({ q, problem: 'no list' }); continue; }
    rows = await read();
    if (!rows || rows.length !== 4) { res.fail++; res.fails.push({ q, problem: 'no list 2' }); continue; }
    // ensure every row has a handle
    if (rows.some(r => !r.h)) { res.fail++; res.fails.push({ q, problem: 'missing handle' }); continue; }

    // pick maj (row 0) and a min (a different type among 1,2,3)
    let maj = rows[0].type;
    let min = null;
    for (let i = 1; i < 4; i++) if (rows[i].type !== maj) { min = rows[i].type; break; }
    if (!min) { res.fail++; res.fails.push({ q, problem: 'no second type' }); continue; }
    const majRow = rows.find(r => r.type === maj);
    const minRow = rows.find(r => r.type === min);

    // DRAG FROM THE HANDLE of majRow to the TOP
    await dragMouse(majRow.h.cx, majRow.h.cy, rows[0].h.cx, rows[0].top + 4);
    await sleep(140);
    const after = await read();
    if (!after || after.length !== 4) { res.fail++; res.fails.push({ q, problem: 'after maj drag' }); continue; }
    const minRow2 = after.find(r => r.type === min);
    if (!minRow2) { res.fail++; res.fails.push({ q, problem: 'no min after' }); continue; }

    // DRAG FROM THE HANDLE of minRow2 to the BOTTOM
    await dragMouse(minRow2.h.cx, minRow2.h.cy, after[3].h.cx, after[3].bottom - 4);
    await sleep(140);

    const fin = await read();
    const got = fin && fin.length === 4 ? fin.map(r => r.type) : null;
    const ok = got && got[0] === maj && got[3] === min;
    if (ok) res.ok++; else { res.fail++; res.fails.push({ q, got, want: [maj, null, null, min] }); }
    res.tested++;
  }

  console.log('\nTOUCH(HANDLE) DRAG RESULT:', JSON.stringify({
    tested: res.tested, ok: res.ok, fail: res.fail,
    fails: res.fails, console_errors: errors,
  }, null, 2));
  await browser.close();
}
