  });

  async function drag(sx, sy, dx, dy) {
    console.log('  drag from', [sx,sy], 'to', [dx,dy]);
    const before = await page.evaluate(() => {
      const el = document.elementFromPoint(arguments[0] !== undefined ? null : null);
      return 'x';
    });
    // what's under the start point?
    const underStart = await page.evaluate((x, y) => {
      const el = document.elementFromPoint(x, y);
      return el ? (el.className || el.tagName + (el.id ? '#'+el.id : '')) : 'null';
    }, sx, sy);
    console.log('  under start point:', underStart);
    await page.mouse.move(sx, sy, { steps: 6 });
    await sleep(40);
    await page.mouse.down();
    await sleep(50);
    // what's under after down?
    for (let i = 1; i <= 10; i++) {
      const cx = sx + (dx - sx) * (i / 10);
      const cy = sy + (dy - sy) * (i / 10);
      await page.mouse.move(cx, cy, { steps: 4 });
      await sleep(30);
    }
    await page.mouse.up();
    await sleep(200);
  };

  const read = async () => {
    return page.evaluate(() => {
      const pane = document.querySelector('.pane.is-active');
      const ul = pane ? pane.querySelector('ul.disc-list') : null;
      if (!ul) return null;
      return [...ul.children].map((li,i) => {
        const r = li.getBoundingClientRect();
        const h = li.querySelector('.disc-handle');
        const hr = h ? h.getBoundingClientRect() : null;
        return { i, t: li.getAttribute('data-type'), text: li.textContent.trim(),
                 cx: r.left + r.width/2, cy: r.top + r.height/2, top: r.top, bottom: r.bottom,
                 h: hr ? { cx: hr.left+hr.width/2, cy: hr.top+hr.height/2 } : null,
                 pe: hr ? getComputedStyle(h).pointerEvents : null };
      });
    });
  };

