  let a = await read();
  console.log('  after: ' + a.map(r=>r.t).join(','));

  // inspect d handle now
  const d = a.find(r=>r.t==='d');
  console.log('\n  d now at idx', d ? d.i : 'NONE', d && d.h ? `handle pe=${d.pe} rect=(${d.h.cy})` : '');
  console.log('  under d.handle?');
  const underD = await page.evaluate((x, y) => {
    const el = document.elementFromPoint(x, y);
    return el ? (el.className || el.tagName + (el.id ? '#'+el.id : '')) : 'null';
  }, d.h.cx, d.h.cy);
  console.log('  under d handle point:', underD);

  const last = a[3];
  console.log('\n--- drag 2: d to bottom ---');
  drag(d.h.cx, d.h.cy, last.h.cx, last.bottom - 4);
  const fin = await read();
  console.log('  final: ' + fin.map(r=>r.t).join(','));
  console.log('  want: [s,c,i,d]');

  console.log('\nerrors:', errors.length ? errors : 'none');
  console.log('console:', logs.length ? logs.slice(-10) : 'none');
  await browser.close();
}
