const puppeteer = require('puppeteer-core');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const HTML = 'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-g6pon0a9/run/index.html';
const COARSE = process.env.COARSE === '1';

async function main() {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/google-chrome',
    headless: true,
    args: ['--no-sandbox','--disable-gpu','--disable-dev-shm-usage','--no-first-run','--no-default-browser-check'],
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 900 });
  if (COARSE) {
    await page.evaluateOnNewDocument(() => {
      const orig = window.matchMedia.bind(window);
      window.matchMedia = function (query) {
        if (query && query.trim() === '(pointer: coarse)')
          return { matches: true, media: query, atQuery: query, onchange: false, change: ()=>{}, removeListener: ()=>{}, addListener: ()=>{} };
        return orig(query);
      };
    });
  }
  const errors = [];
  page.on('pageerror', e => errors.push(String(e).slice(0,200)));
  await page.goto(HTML, { waitUntil: 'load', timeout: 30000 });
  await sleep(700);
  await page.click('[data-modal-open]');
  await sleep(600);

  const dragMouse = async (sx, sy, dx, dy, steps = 14) => {
    if (![sx,sy,dx,dy].every(Number.isFinite))
      throw new Error('bad drag coords s=(' + sx + ',' + sy + ') d=(' + dx + ',' + dy + ')');
    await page.mouse.move(sx, sy, { steps: 6 });
    await sleep(40);
    await page.mouse.down();
    await sleep(30);
    for (let i = 1; i <= steps; i++) {
      await page.mouse.move(sx + (dx - sx) * (i / steps), sy + (dy - sy) * (i / steps), { steps: 4 });
      await sleep(20);
    }
    await page.mouse.up();
    await sleep(60);
  };

  const read = async (qi) => {
    return page.evaluate((qiArg) => {
      const pane = document.querySelector('.pane.is-active');
      if (!pane) return null;
      const ul = [...pane.querySelectorAll('ul.disc-list')][qiArg % 3];
      if (!ul) return null;
      return [...ul.children].map(li => {
        const r = li.getBoundingClientRect();
        return { t: li.getAttribute('data-type'), cx: r.left + r.width/2,
                 cy: r.top + r.height/2, top: r.top, bottom: r.bottom };
      });
    }, qi);
  };

  const res = { ok: 0, fail: 0, tested: 0, fails: [] };
  for (let q = 0; q < 5; q++) {
    await page.evaluate((qi) => {
      const ul = [...document.querySelector('.pane.is-active').querySelectorAll('ul.disc-list')][qi % 3];
      if (ul) ul.scrollIntoView({ block: 'center', behavior: 'instant' });
    }, q);
    await sleep(250);

    let rows = await read(q);
    rows = await read(q);
    if (!rows || rows.length !== 4) { res.fail++; res.fails.push({ q, problem: 'no list' }); continue; }

    // item idx 2 -> top ; original idx 0 -> bottom
    await dragMouse(rows[2].cx, rows[2].cy, rows[0].cx, rows[0].top + 5);
    await sleep(140);
    let after = await read(q);
    if (!after || after.length !== 4) { res.fail++; res.fails.push({ q, problem: 'after drag1' }); continue; }
    await dragMouse(after[1].cx, after[1].cy, after[3].cx, after[3].bottom - 5);
    await sleep(140);

    const fin = await read(q);
    const got = fin && fin.length === 4 ? fin.map(r => r.t) : null;
    const want = [rows[2].t, rows[1].t, rows[3].t, rows[0].t];
    const ok = got && got.join(',') === want.join(',');
    if (ok) res.ok++; else { res.fail++; res.fails.push({ q, got, want }); }
    res.tested++;
  }

  console.log('COARSE=', COARSE, 'RESULT:', JSON.stringify({
    tested: res.tested, ok: res.ok, fail: res.fail,
    fails: res.fails, console_errors: errors.length ? errors : 'none'
  }, null, 2));
  await browser.close();
}
main().catch(e => { console.error(e); process.exit(1); });

